import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.C5oN-8Wt.js";const _=JSON.parse('{"title":"信道模拟器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/channel_model/index.md","filePath":"v0.1.0-alpha/modules/channel_model/index.md"}'),c={name:"v0.1.0-alpha/modules/channel_model/index.md"};function r(l,t,n,i,h,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="信道模拟器" tabindex="-1">信道模拟器 <a class="header-anchor" href="#信道模拟器" aria-label="Permalink to &quot;信道模拟器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>channel_model</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>对复数流模拟多径、频偏、时钟比例变化和加性噪声，用于观察理想星座怎样变成接收端数据。它帮助逐项研究信道影响，实际结果由输入与设置共同决定。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>符号映射器.out → 信道模拟器.in → 符号判决器.in</code>。保留映射器到另一判决器的直接分支，区分映射规则与信道造成的变化。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（复数输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（复数输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>先一次只加入一种影响。噪声幅度是随机扰动尺度，不是 SNR；频偏会让相位持续旋转，按实际输出率换算。时钟比例定义为输入率／输出率，因此输出率等于输入率除以实际比例。</p><p><code>frequency_hz</code> 必须满足 <code>[-Fs_out/2, Fs_out/2)</code>，其中 <code>Fs_out = Fs_in / epsilon_actual</code>，<code>epsilon_actual</code> 是实际用于运行的单精度时钟比例。参数表中的静态范围 <code>[-500000, 500000]</code> 不是接线后的完整范围；还须根据上游速率和这个输出率限制频偏。</p><p>复数 taps 的实虚部列表等长，第 k 项对应 k 个输出周期的多径延迟。即使比例为 1、没有噪声和频偏，当前原生信道仍有 3 采样前视，Master 保留其输出时间轴，不自动平移伪装成逐点直通。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>噪声幅度（非 SNR）<br><code>noise_amplitude</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>种子模式<br><code>seed_mode</code></td><td><code>fixed</code></td><td>固定 (<code>fixed</code>)；系统时间 (<code>system_time</code>)</td><td>重新准备</td></tr><tr><td>噪声种子<br><code>noise_seed</code></td><td><code>0</code></td><td>范围 0 至 2147483646</td><td>重新准备</td></tr><tr><td>频偏 (Hz)<br><code>frequency_hz</code></td><td><code>0</code></td><td>范围 -500000 至 500000</td><td>可在线应用</td></tr><tr><td>复数 taps 实部<br><code>taps_real</code></td><td><code>[1]</code></td><td>实部、虚部列表等长；第 k 项延迟 k 个输出采样周期。锁定 GNU 3.10.12、epsilon=1 时有 3 采样前视；保留原输出时间轴，不自动对齐。</td><td>可在线应用</td></tr><tr><td>复数 taps 虚部<br><code>taps_imag</code></td><td><code>[0]</code></td><td>实部、虚部列表等长；第 k 项延迟 k 个输出采样周期。锁定 GNU 3.10.12、epsilon=1 时有 3 采样前视；保留原输出时间轴，不自动对齐。</td><td>可在线应用</td></tr><tr><td>时钟比例（输入率 / 输出率）<br><code>epsilon</code></td><td><code>1</code></td><td>范围 0.0009765625 至 1024；本版支持 1/1024–1024，GNU 按实际单精度比例运行；频偏按输出速率换算。</td><td>重新准备</td></tr><tr><td>阻断流标签<br><code>block_tags</code></td><td><code>false</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>noise_amplitude</code></li><li><code>frequency_hz</code></li><li><code>taps_real</code>、<code>taps_imag</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线改变扰动或 taps 后，看实际回执与输出，不能将消息排队当作样本已经采用新值。时钟比例、随机种子和标签阻断规则变化后重新准备；标签设置改变元数据传播，不代替信号处理。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="qpsk-映射、判决与理想信道" tabindex="-1">QPSK 映射、判决与理想信道 <a class="header-anchor" href="#qpsk-映射、判决与理想信道" aria-label="Permalink to &quot;QPSK 映射、判决与理想信道&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/qpsk-channel.cnsproj" download>下载 qpsk-channel.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>QPSK 映射、判决与理想信道</p><ul><li>直接判决逐码元一致。理想信道仍保留 GNU 原生 3 点前视，不能将信道两端同索引当作已对齐。</li></ul><p>QPSK 示例从理想配置开始。直接判决逐索引对应源；信道输出的前段与映射器更后 3 个样本对应，经过该已知位置关系核对后再比较判决。接着可分别增加噪声或频偏，观察星座散布或旋转。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>参数看似理想，为什么两端同位置不同？</strong> 检查原生前视及滤波历史，先确认样本对应关系。</p><p><strong>星座一直旋转，判决器为什么不跟着转？</strong> 信道频偏改变相位，固定星座硬判决不会自动完成载波同步。</p>',29)])])}const u=d(c,[["render",r]]);export{_ as __pageData,u as default};
